<?php require __DIR__.'/_init.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$act=$_POST['action']??'save';if($act==='delete'){$id=(int)$_POST['id'];$q=$pdo->prepare('SELECT image FROM banners WHERE id=?');$q->execute([$id]);$img=$q->fetchColumn();if($img)@unlink(__DIR__.'/../storage/uploads/'.$img);$pdo->prepare('DELETE FROM banners WHERE id=?')->execute([$id]);flash('success','بنر حذف شد.');}else{$title=trim((string)($_POST['title']??''));$subtitle=trim((string)($_POST['subtitle']??''));$link=trim((string)($_POST['link_url']??''));$sort=(int)($_POST['sort_order']??0);$active=isset($_POST['is_active'])?1:0;$img=null;if(isset($_FILES['image'])&&($_FILES['image']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){try{$f=safe_upload($_FILES['image'],['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'],'uploads',(int)($config['upload_max_bytes']??5242880));$img=$f['name'];}catch(Throwable $e){flash('error',$e->getMessage());header('Location: '.site_url('admin/banners.php'));exit;}}if($title===''){flash('error','عنوان بنر الزامی است.');}else{$pdo->prepare('INSERT INTO banners(title,subtitle,image,link_url,sort_order,is_active,created_at) VALUES(?,?,?,?,?,?,NOW())')->execute([$title,$subtitle,$img,$link,$sort,$active]);flash('success','بنر اضافه شد.');}}header('Location: '.site_url('admin/banners.php'));exit;}$rows=$pdo->query('SELECT * FROM banners ORDER BY sort_order,id DESC')->fetchAll();render_header('مدیریت بنرها');?><main class="container"><div class="page-title"><h1>مدیریت بنرها</h1><p>بارگذاری تصویر بنر و تعیین مقصد لینک.</p></div><div class="admin-layout"><aside class="admin-nav"><a href="<?=e(site_url('admin/index.php'))?>">داشبورد</a><a href="<?=e(site_url('admin/products.php'))?>">محصولات</a><a href="<?=e(site_url('admin/orders.php'))?>">سفارش‌ها</a><a href="<?=e(site_url('admin/settings.php'))?>">تنظیمات سایت</a></aside><section class="admin-content"><div class="form-card"><h2>افزودن بنر</h2><form method="post" enctype="multipart/form-data"><?=csrf_field()?><div class="form-grid"><div class="form-group"><label>عنوان</label><input name="title" required></div><div class="form-group"><label>زیرعنوان</label><input name="subtitle"></div><div class="form-group"><label>لینک مقصد (اختیاری)</label><input name="link_url" type="url" placeholder="https://..."></div><div class="form-group"><label>تصویر JPG/PNG/WEBP</label><input type="file" name="image" accept="image/jpeg,image/png,image/webp"></div><div class="form-group"><label>ترتیب نمایش</label><input type="number" name="sort_order" value="0"></div><div class="form-group"><label><input type="checkbox" name="is_active" checked> فعال</label></div></div><button class="btn">ذخیره بنر</button></form></div><div class="table-wrap"><table class="table"><tr><th>تصویر</th><th>عنوان</th><th>وضعیت</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?php if($r['image']):?><img src="<?=e(product_image($r['image']))?>" style="width:100px" alt=""><?php endif;?></td><td><?=e($r['title'])?></td><td><?=$r['is_active']?'فعال':'غیرفعال'?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="small-btn danger">حذف</button></form></td></tr><?php endforeach;?></table></div></section></div></main><?php render_footer();?>
